allCallbacks[0] = callback; 
// wrong usage for System.arraycopy 
// System.arraycopy(allCallbacks, 1, callbacks, 0, callbacks.length); 
System.arraycopy(callbacks, 0, allCallbacks, 1, callbacks.length);

